#include "exercise.h"
bool align_up(uint32_t value,uint32_t alignment,uint32_t *out) {
 if(!alignment || (alignment & (alignment-1u))) return false;
 uint32_t mask=alignment-1u;
 if(value>UINT32_MAX-mask) return false;
 *out=(value+mask)&~mask; return true;
}

